function sanitize(val) {
  if (val === null || val === undefined) return '';
  return String(val).replace(/'/g, "''").trim();
}
const b = items[0].json.body || items[0].json;
return [{ json: {
  naam:          sanitize(b.naam),
  type:          sanitize(b.type || 'klant'),
  contactpersoon: sanitize(b.contactpersoon),
  adres:         sanitize(b.adres),
  postcode:      sanitize(b.postcode),
  plaats:        sanitize(b.plaats),
  land:          sanitize(b.land || 'Nederland'),
  email:         sanitize(b.email),
  telefoon:      sanitize(b.telefoon),
  btw_nummer:    sanitize(b.btw_nummer),
  kvk_nummer:    sanitize(b.kvk_nummer),
  iban:          sanitize(b.iban),
  notities:      sanitize(b.notities)
}}];

const output = items[0].json.stdout || '';
const rows = output.split('\n').map(r => r.trim()).filter(Boolean);
const naam = $node['Function: Input valideren'].json.naam;
return [{ json: {
  klanten: rows,
  bericht: `Klant '${naam}' opgeslagen. ${rows.length} klant(en) in systeem.`
}}];
